/* Яндекс Диск — источник файлов для всех приложений Пульс Офиса (поле «источник» описания).

   Вход и выход — только здесь, в панели плагина. «Войти» открывает окно входа Яндекса
   (диалог.вход: логин и пароль или «Разрешить», если вход в Яндекс уже выполнен) — в приложении для
   Windows и телефонов и в браузере на сайте Пульса; возврат ловит приложение (или страница сайта),
   код подтверждения меняется на ключ (OAuth с PKCE, без секрета приложения). Где окно входа не
   поймать (страница, открытая с диска, — {нельзя}), — QR-код и код на экране (OAuth device flow):
   человек подтверждает вход на странице Яндекса, плагин сам замечает это. Ключ человек не видит и
   никуда не переносит: он лежит в хранилище плагина ТАЙНО (на диске — шифром, см. PLUGSTORE) и
   помнится до «Выйти». Пока ключа нет, окна «Открыть» и «Сохранить как» приложений облака не
   показывают: описание называет ключ хранилища, по которому страница видит вход («источник.вход»).

   Окно облака (CLOUD на странице) зовёт функции источника: список, прочитать, записать, создатьПапку.
   Доводы — параметры(), байты — Uint8Array туда и обратно. Ключ перестал действовать (отозван,
   истёк и не обновился) — плагин его забывает и отвечает {нужноВойти}.

   ClientID приложения «Пульс Офис» на oauth.yandex.ru (права cloud_api:disk.read, disk.write,
   disk.info) — CLIENT_ID ниже, секрета у приложения нет.                                          */
/* ===== QR-код (ISO/IEC 18004): байтовый режим, UTF-8, уровень коррекции M, версии 1–40 ===== */
const QR = (() => {
  const ECC_M = [-1, 10, 16, 26, 18, 24, 16, 18, 22, 22, 26, 30, 22, 22, 24, 24, 28, 28, 26, 26, 26, 26, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28];
  const БЛОКИ_M = [-1, 1, 1, 1, 2, 2, 4, 4, 4, 5, 5, 5, 8, 9, 9, 10, 10, 11, 13, 14, 16, 17, 17, 18, 20, 21, 23, 25, 26, 28, 29, 31, 33, 35, 37, 38, 40, 43, 45, 47, 49];
  const модулей = v => { let r = (16 * v + 128) * v + 64; if(v >= 2){ const n = Math.floor(v / 7) + 2; r -= (25 * n - 10) * n - 55; if(v >= 7) r -= 36; } return r; };
  const данных = v => Math.floor(модулей(v) / 8) - ECC_M[v] * БЛОКИ_M[v];
  const умн = (x, y) => { let z = 0; for(let i = 7; i >= 0; i--){ z = (z << 1) ^ ((z >>> 7) * 0x11D); z ^= ((y >>> i) & 1) * x; } return z; };
  function делитель(n){
    const р = new Array(n).fill(0); р[n - 1] = 1; let корень = 1;
    for(let i = 0; i < n; i++){ for(let j = 0; j < n; j++){ р[j] = умн(р[j], корень); if(j + 1 < n) р[j] ^= р[j + 1]; } корень = умн(корень, 2); }
    return р;
  }
  function остаток(данные, д){
    const р = new Array(д.length).fill(0);
    for(const b of данные){ const f = b ^ р.shift(); р.push(0); д.forEach((k, i) => { р[i] ^= умн(k, f); }); }
    return р;
  }
  function utf8(т){ const out = []; for(const ch of String(т)){ let c = ch.codePointAt(0);
    if(c < 0x80) out.push(c); else if(c < 0x800) out.push(0xC0 | c >> 6, 0x80 | c & 63);
    else if(c < 0x10000) out.push(0xE0 | c >> 12, 0x80 | c >> 6 & 63, 0x80 | c & 63);
    else out.push(0xF0 | c >> 18, 0x80 | c >> 12 & 63, 0x80 | c >> 6 & 63, 0x80 | c & 63); } return out; }
  function выравнивание(v){
    if(v === 1) return [];
    const n = Math.floor(v / 7) + 2, шаг = v === 32 ? 26 : Math.ceil((v * 4 + 4) / (n * 2 - 2)) * 2, р = [6];
    for(let pos = v * 4 + 10; р.length < n; pos -= шаг) р.splice(1, 0, pos);
    return р;
  }
  function сделать(текст){
    const байты = utf8(текст);
    let v = 1;
    for(; v <= 40; v++){ const бит = 4 + (v < 10 ? 8 : 16) + 8 * байты.length; if(бит <= данных(v) * 8) break; }
    if(v > 40) throw new Error('Слишком длинный текст для QR-кода');
    /* поток битов */
    const биты = [];
    const доб = (x, n) => { for(let i = n - 1; i >= 0; i--) биты.push((x >>> i) & 1); };
    доб(4, 4); доб(байты.length, v < 10 ? 8 : 16); байты.forEach(b => доб(b, 8));
    const ёмк = данных(v) * 8;
    доб(0, Math.min(4, ёмк - биты.length));
    доб(0, (8 - биты.length % 8) % 8);
    for(let p = 0xEC; биты.length < ёмк; p ^= 0xEC ^ 0x11) доб(p, 8);
    const слова = []; for(let i = 0; i < биты.length; i += 8){ let b = 0; for(let j = 0; j < 8; j++) b = b << 1 | биты[i + j]; слова.push(b); }
    /* блоки и коррекция, чередование */
    const nБ = БЛОКИ_M[v], eБ = ECC_M[v], всего = Math.floor(модулей(v) / 8), коротких = nБ - всего % nБ, длКор = Math.floor(всего / nБ), д = делитель(eБ);
    const блоки = []; let k = 0;
    for(let i = 0; i < nБ; i++){
      const dat = слова.slice(k, k + длКор - eБ + (i < коротких ? 0 : 1)); k += dat.length;
      const ecc = остаток(dat, д); if(i < коротких) dat.push(0);
      блоки.push(dat.concat(ecc));
    }
    const поток = [];
    for(let i = 0; i < блоки[0].length; i++) блоки.forEach((б, j) => { if(i !== длКор - eБ || j >= коротких) поток.push(б[i]); });
    /* поле */
    const N = v * 4 + 17, м = Array.from({length: N}, () => new Array(N).fill(false)), служ = Array.from({length: N}, () => new Array(N).fill(false));
    const ставь = (x, y, тёмн) => { м[y][x] = тёмн; служ[y][x] = true; };
    for(let i = 0; i < N; i++){ ставь(6, i, i % 2 === 0); ставь(i, 6, i % 2 === 0); }
    const искатель = (x, y) => { for(let dy = -4; dy <= 4; dy++) for(let dx = -4; dx <= 4; dx++){ const d = Math.max(Math.abs(dx), Math.abs(dy)), xx = x + dx, yy = y + dy; if(xx >= 0 && xx < N && yy >= 0 && yy < N) ставь(xx, yy, d !== 2 && d !== 4); } };
    искатель(3, 3); искатель(N - 4, 3); искатель(3, N - 4);
    const ал = выравнивание(v), na = ал.length;
    for(let i = 0; i < na; i++) for(let j = 0; j < na; j++){
      if((i === 0 && j === 0) || (i === 0 && j === na - 1) || (i === na - 1 && j === 0)) continue;
      for(let dy = -2; dy <= 2; dy++) for(let dx = -2; dx <= 2; dx++) ставь(ал[i] + dx, ал[j] + dy, Math.max(Math.abs(dx), Math.abs(dy)) !== 1);
    }
    const формат = маска => {
      const data = 0 << 3 | маска; let r = data;                 /* уровень M: биты 00 */
      for(let i = 0; i < 10; i++) r = (r << 1) ^ ((r >>> 9) * 0x537);
      const b = (data << 10 | r) ^ 0x5412, бит = i => ((b >>> i) & 1) === 1;
      for(let i = 0; i <= 5; i++) ставь(8, i, бит(i));
      ставь(8, 7, бит(6)); ставь(8, 8, бит(7)); ставь(7, 8, бит(8));
      for(let i = 9; i < 15; i++) ставь(14 - i, 8, бит(i));
      for(let i = 0; i < 8; i++) ставь(N - 1 - i, 8, бит(i));
      for(let i = 8; i < 15; i++) ставь(8, N - 15 + i, бит(i));
      ставь(8, N - 8, true);
    };
    формат(0);
    if(v >= 7){
      let r = v; for(let i = 0; i < 12; i++) r = (r << 1) ^ ((r >>> 11) * 0x1F25);
      const b = v << 12 | r;
      for(let i = 0; i < 18; i++){ const бит = ((b >>> i) & 1) === 1, a = N - 11 + i % 3, c = Math.floor(i / 3); ставь(a, c, бит); ставь(c, a, бит); }
    }
    /* данные змейкой */
    let i = 0;
    for(let право = N - 1; право >= 1; право -= 2){
      if(право === 6) право = 5;
      for(let верт = 0; верт < N; верт++) for(let j = 0; j < 2; j++){
        const x = право - j, вверх = ((право + 1) & 2) === 0, y = вверх ? N - 1 - верт : верт;
        if(!служ[y][x] && i < поток.length * 8){ м[y][x] = ((поток[i >>> 3] >>> (7 - (i & 7))) & 1) === 1; i++; }
      }
    }
    const МАСКИ = [(x, y) => (x + y) % 2 === 0, (x, y) => y % 2 === 0, (x, y) => x % 3 === 0, (x, y) => (x + y) % 3 === 0, (x, y) => (Math.floor(x / 3) + Math.floor(y / 2)) % 2 === 0,
      (x, y) => x * y % 2 + x * y % 3 === 0, (x, y) => (x * y % 2 + x * y % 3) % 2 === 0, (x, y) => ((x + y) % 2 + x * y % 3) % 2 === 0];
    const наложить = k => { for(let y = 0; y < N; y++) for(let x = 0; x < N; x++) if(!служ[y][x] && МАСКИ[k](x, y)) м[y][x] = !м[y][x]; };
    const штраф = () => {
      let s = 0, тёмных = 0;
      const линия = get => { let ряд = 1; for(let k = 1; k < N; k++){ if(get(k) === get(k - 1)) ряд++; else { if(ряд >= 5) s += ряд - 2; ряд = 1; } } if(ряд >= 5) s += ряд - 2;
        for(let k = 0; k + 6 < N; k++){ if(get(k) && !get(k + 1) && get(k + 2) && get(k + 3) && get(k + 4) && !get(k + 5) && get(k + 6)){
          const до = k >= 4 && !get(k - 1) && !get(k - 2) && !get(k - 3) && !get(k - 4), после = k + 10 < N && !get(k + 7) && !get(k + 8) && !get(k + 9) && !get(k + 10);
          if(до || после) s += 40; } } };
      for(let y = 0; y < N; y++){ линия(x => м[y][x]); линия(x => м[x][y]); }
      for(let y = 0; y + 1 < N; y++) for(let x = 0; x + 1 < N; x++){ const c = м[y][x]; if(c === м[y][x + 1] && c === м[y + 1][x] && c === м[y + 1][x + 1]) s += 3; }
      for(let y = 0; y < N; y++) for(let x = 0; x < N; x++) if(м[y][x]) тёмных++;
      return s + (Math.ceil(Math.abs(тёмных * 20 - N * N * 10) / (N * N)) - 1) * 10;
    };
    let лучшая = 0, мин = Infinity;
    for(let k = 0; k < 8; k++){ наложить(k); формат(k); const s = штраф(); if(s < мин){ мин = s; лучшая = k; } наложить(k); }
    наложить(лучшая); формат(лучшая);
    return {размер: N, версия: v, модули: м};
  }
  function svg(текст, точек = 160){
    const q = сделать(текст), N = q.размер, поле = 4, всего = N + 2 * поле;
    let путь = '';
    for(let y = 0; y < N; y++) for(let x = 0; x < N; x++) if(q.модули[y][x]) путь += 'M' + (x + поле) + ' ' + (y + поле) + 'h1v1h-1z';
    return '<svg xmlns="http://www.w3.org/2000/svg" width="' + точек + '" height="' + точек + '" viewBox="0 0 ' + всего + ' ' + всего + '" shape-rendering="crispEdges"><rect width="' + всего + '" height="' + всего + '" fill="#fff"/><path d="' + путь + '" fill="#000"/></svg>';
  }
  return {сделать, svg};
})();
