  if(код === 401){ const e = new Error('Вход в Яндекс Диск истёк — войдите снова'); e.нужноВойти = true; return e; }
  if(код === 403) return new Error((что ? что + ': ' : '') + 'нет доступа' + (т.description ? ' (' + т.description + ')' : ''));
  if(код === 404) return new Error((что ? что + ': ' : '') + 'на Диске нет такого файла или папки');
  if(код === 409) return new Error((что ? что + ': ' : '') + 'такой файл или папка уже есть');
  if(код === 413) return new Error((что ? что + ': ' : '') + 'файл слишком большой для Диска');
  if(код === 423) return new Error((что ? что + ': ' : '') + 'файл занят другой операцией на Диске — попробуйте через минуту');
  if(код === 429) return new Error('Яндекс Диск просит подождать: слишком много запросов');
  if(код === 507 || /InsufficientStorage/.test(ош)) return new Error('На Яндекс Диске не хватает места');
  if(код >= 500) return new Error('Яндекс Диск сейчас недоступен (ответ ' + код + ') — попробуйте позже');
  return new Error((что ? что + ': ' : '') + 'Яндекс Диск ответил ' + код + (т.description || т.message ? ' — ' + (т.description || т.message) : ''));
}
/* Запрос к API Диска с ключом; истёк — один раз обновить ключ и повторить. */
async function диск(путь, о){
  let к = ключ();
  if(!к || !к.доступ){ const e = new Error('Нужно войти в Яндекс Диск'); e.нужноВойти = true; throw e; }
  const сделать = к2 => сеть(API + путь, Object.assign({}, о, {заголовки: Object.assign({Accept: 'application/json', Authorization: 'OAuth ' + к2.доступ}, (о && о.заголовки) || {})}));
  let r = await сделать(к);
  if(r.код === 401 && к.обновление){
    const н = await обновить(к);
    if(н){ к = н; r = await сделать(к); }
  }
  /* ключ больше не действует (отозван на странице Яндекса, истёк) — забываем: окна приложений
     перестанут предлагать Диск, пока не войти снова */
  if(r.код === 401){ забытьКлюч(); показатьСостояние(); }
  return r;
}
async function обновить(к){
  let r;
  try { r = await сеть(OAUTH + 'token', {метод: 'POST', заголовки: {'Content-Type': 'application/x-www-form-urlencoded'},
    тело: форма(Object.assign({grant_type: 'refresh_token', refresh_token: к.обновление}, приложение()))}, 1); }
  catch(e){ return null; }
  const т = r && r.тело;
  if(!r || !r.ок || !т || !т.access_token) return null;
  const н = {доступ: т.access_token, обновление: т.refresh_token || к.обновление, до: т.expires_in ? Date.now() + т.expires_in * 1000 : 0};
  положитьКлюч(н);
