}
const нужноВойти = текст => ({нужноВойти: true, текст: текст || 'Нужно войти в Яндекс Диск'});
async function безВхода(f){
  try { return await f(); }
  catch(e){ if(e && e.нужноВойти) return нужноВойти(e.message); throw e; }
}

/* --- кто вошёл --- */
