  if(к){ панель.поле('состояние', 'да'); панель.поле('кто', [{текст: 'Вход выполнен: '}, {текст: хранилище.взять('кто', '') || 'Яндекс', жирный: true}]); return; }
  /* сначала код, потом состояние: иначе на миг виден прежний код */
  if(ж && ж.до > Date.now()){ показатьКод(ж); панель.поле('состояние', 'ждём'); return; }
  панель.поле('код', '');
