    const q = QR.сделать(ж.адрес), N = q.размер, шаг = Math.floor(200 / (N + 8)), от = Math.floor((200 - шаг * N) / 2);
    let d = '';
    for(let y = 0; y < N; y++) for(let x = 0; x < N; x++) if(q.модули[y][x]) d += 'M' + (от + x * шаг) + ' ' + (от + y * шаг) + 'h' + шаг + 'v' + шаг + 'h-' + шаг + 'z';
    панель.холст('qr', [{вид: 'очистить', заливка: '#ffffff'}, {вид: 'путь', d: d, заливка: '#000000'}]);
  } catch(e){}
  const код = String(ж.код).replace(/^(.{4})(.{4})$/, '$1 $2');
  const до = new Date(ж.до), чм = String(до.getHours()).padStart(2, '0') + ':' + String(до.getMinutes()).padStart(2, '0');
  панель.поле('код', [{текст: 'Отсканируйте QR-код телефоном или откройте страницу входа и введите код '}, {текст: код, жирный: true},
    {текст: ' · до ' + чм + ', потом — новый', цвет: '#667085'}]);
