const ВОЗВРАТ = 'https://oauth.yandex.ru/verification_code';     // Redirect URI приложения: его ловит окно приложения
const base64url = u8 => btoa(String.fromCharCode.apply(null, Array.from(u8))).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
function случайно(n){
  const b = new Uint8Array(n); crypto.getRandomValues(b);
