}
/* code_verifier и code_challenge (S256): SHA-256 — своим кодом (sha256.js), в песочном потоке crypto.subtle нет */
function проверка(){
  const v = случайно(48);                                       // 64 знака из [A-Za-z0-9-_]
  return {v, вызов: base64url(SHA256.текст(v)), метод: 'S256'};
