/* --- вход кодом на экране (OAuth device flow): где окна входа нет (страница, открытая с диска) ---
   Код живёт у Яндекса минуты (expires_in). Истёк — плагин сам берёт новый и показывает его на месте:
   окно кода не закрывается (до ПРОДЛЕНИЙ раз — полчаса; дальше тихо назад к «Войти»). Ожидание идёт
   таймером потока, вне вызова: «Войти» отвечает сразу, закрытая панель вход не обрывает. Опрашивает
   Яндекс только поток, где нажали «Войти» или открыли панель (приОткрытии): фоновые потоки других
   приложений набора лишь показывают состояние — опросы одного кода чаще interval Яндекс отвергает.
   Сбой связи, «реже», 429 и 5xx — ждём дольше; отказ на странице Яндекса — словами; код отвергнут
   (invalid_grant) сразу после выдачи второй раз подряд — дело не в сроке: словами, что ответил Яндекс. */
const ПРОДЛЕНИЙ = 6;
async function новыйКод(продлений, сразу){
  let r = null, беда = '';
  try {
    r = await сеть(OAUTH + 'device/code', {метод: 'POST', заголовки: {'Content-Type': 'application/x-www-form-urlencoded'},
      тело: форма({client_id: CLIENT_ID, device_id: устройство(), device_name: ИМЯ_УСТРОЙСТВА})}, 2);
  } catch(e){ беда = e.message; }
  const т = r && r.тело;
  if(!(r && r.ок && т && т.device_code && т.user_code)){
    if(!беда) беда = 'Яндекс ответил ' + (r ? r.код : '?') + (т && (т.error_description || т.error) ? ' — ' + (т.error_description || т.error) : '');
    хранилище.убрать('ожидание');
    показатьСостояние('Войти не удалось: ' + беда);
    return null;
  }
  const сейчас = Date.now();
  const ж = {устройство: т.device_code, код: String(т.user_code), адрес: String(т.verification_url || 'https://oauth.yandex.ru/device'),
    выдан: сейчас, до: сейчас + (+т.expires_in || 300) * 1000, шаг: Math.max(2, +т.interval || 5) * 1000, продлений, сразу};
  хранилище.тайно('ожидание', ж);
  показатьСостояние();
  ждать(ж);
  return ж;
}
async function продлить(ж, сразу){
  if(ж.продлений >= ПРОДЛЕНИЙ){ хранилище.убрать('ожидание'); показатьСостояние(); return; }
  await новыйКод(ж.продлений + 1, сразу);
}
function ждать(ж){
  if(таймер) clearTimeout(таймер);
  таймер = setTimeout(() => опрос(ж), ж.шаг);
}
/* ожидание всё ещё этого кода? Вошли, «Отмена» — нет; код сменил другой поток — показать его */
function тотЖе(ж){
  const сейчас = хранилище.взять('ожидание', null);
  if(ключ() || !сейчас) return false;
  if(сейчас.устройство !== ж.устройство){ показатьСостояние(); return false; }
  return true;
}
async function опрос(ж){
  таймер = null;
  if(!тотЖе(ж)) return;
  if(Date.now() > ж.до){ await продлить(ж, 0); return; }
  let r;
  try {
    r = await сеть(OAUTH + 'token', {метод: 'POST', заголовки: {'Content-Type': 'application/x-www-form-urlencoded'},
      тело: форма(Object.assign({grant_type: 'device_code', code: ж.устройство}, приложение()))}, 1);
  } catch(e){ ждать(ж); return; }                                       // связь пропала — подождём ещё
  if(!тотЖе(ж)) return;
  const т = r.тело || {};
  if(r.ок && т.access_token){
    хранилище.убрать('ожидание');
    положитьКлюч({доступ: т.access_token, обновление: т.refresh_token || '', до: т.expires_in ? Date.now() + т.expires_in * 1000 : 0});
