      показатьСостояние('Яндекс не принимает код: ' + (т.error_description || т.error));
      return;
    }
    await продлить(ж, рано ? ж.сразу + 1 : 0);                       // истёк — новый на месте старого
    return;
  }
  хранилище.убрать('ожидание');
  показатьСостояние('Войти не удалось: Яндекс ответил ' + (т.error_description || т.error || r.код));
}
function Отмена(){ if(таймер){ clearTimeout(таймер); таймер = null; } хранилище.убрать('ожидание'); показатьСостояние(); }
function Выйти(){ Отмена(); забытьКлюч(); показатьСостояние(); }
/* поток поднялся (страница открыта, документ сменился): только показать состояние — опрашивает не он */
function Состояние(){ показатьСостояние(); }
/* открыли панель: состояние из хранилища; незаконченный вход — опрашивать отсюда; код истёк, пока
