/* --- папки и файлы --- */
const КОРЕНЬ = 'disk:/';
/* Путь Диска: «disk:/…»; пусто, «/», «disk:» — корень; хвостовая косая (кроме корня) — прочь. */
function путьДиска(п){
  let s = String(п || '').trim();
  if(!s || s === '/') return КОРЕНЬ;
  if(!/^(disk|app|trash):/.test(s)) s = КОРЕНЬ + s.replace(/^\/+/, '');
  const m = /^((?:disk|app|trash):)\/*(.*?)\/*$/.exec(s);
  return m[1] + '/' + m[2];
}
const версия = x => x && x.md5 ? 'md5:' + x.md5 : x && x.modified ? 'mod:' + x.modified + ':' + (x.size || 0) : '';
