  return безВхода(async () => {
    const путь = путьДиска(параметры().путь);
    const все = [];
    let смещение = 0, корень = null;
    for(let круг = 0; круг < 50; круг++){
      const r = await диск('resources?' + форма({path: путь, limit: 500, offset: смещение, sort: 'name',
        fields: 'name,path,type,_embedded.items.name,_embedded.items.path,_embedded.items.type,_embedded.items.size,_embedded.items.modified,_embedded.items.md5,_embedded.total,_embedded.limit,_embedded.offset'}), {});
      if(!r.ок) throw бедаДиска(r, 'Папка «' + путь.replace(/^disk:/, '') + '»');
      корень = r.тело || {};
