  const ссылка = async () => {
    if(href) return href;
    const с = await диск('resources/download?' + форма({path: путь}), {});
    if(!с.ок || !с.тело || !с.тело.href) throw бедаДиска(с, 'Скачать «' + имя + '»');
    return (href = String(с.тело.href).replace(/^(https:\/\/[^/:]+):443\//, '$1/'));
  };
  const как = {
    'ссылка': async () => сеть(await ссылка(), {вид: 'байты', срок: 120000}),
    'ссылка+ключ': async () => сеть(await ссылка(), {вид: 'байты', срок: 120000, заголовки: {Authorization: 'OAuth ' + к.доступ}}),
    'webdav': () => сеть(WEBDAV + путь.replace(/^disk:/, '').split('/').map(encodeURIComponent).join('/'), {вид: 'байты', срок: 120000,
      заголовки: {Authorization: 'OAuth ' + к.доступ}}),
  };
  const был = хранилище.взять('скачивание', '');
  const порядок = СПОСОБЫ.includes(был) ? [был].concat(СПОСОБЫ.filter(x => x !== был)) : СПОСОБЫ.slice();
  const беды = [], начало = Date.now();
  for(const способ of порядок){
    let r;
    try { r = await как[способ](); }
    catch(e){
      if(e && e.нужноВойти) throw e;
      беды.push(String((e && e.message) || e));
      if(этоCORS(e)) continue;
      if(способ === был) continue;                                     // запомненный подвёл — пробуем остальные
      break;
    }
    if(r.ок && r.байты){
      if(способ !== был) хранилище.положить('скачивание', способ);
      try { панель.сообщение('Файл «' + имя + '» получен ' + ИМЯ_СПОСОБА[способ] + ' за ' + ((Date.now() - начало) / 1000).toFixed(1).replace('.', ',') + ' с'
        + (беды.length ? '; безуспешных попыток другими способами: ' + беды.length : '') + '.'); } catch(e){}
      return r.байты;
    }
    беды.push(ИМЯ_СПОСОБА[способ] + ': сервер ответил ' + r.код);
    if(r.код === 401 || r.код === 403 || r.код === 404 || способ === был) continue;
    break;
  }
  if(беды.some(б => /CORS|не разрешает странице/.test(б)))
    throw new Error('Яндекс Диск не даёт этой странице скачать «' + имя + '»: его сервер скачивания не разрешает браузеру читать файл (CORS), '
      + 'и обходные пути не помогли. Откройте файл в приложении Пульс Офис для Windows — там файл берёт само приложение, это ограничение не действует. '
      + 'Подробно: ' + беды[0].slice(0, 300));
  throw new Error('Файл «' + имя + '» не скачался: ' + беды.join('; ').slice(0, 400));
}
/* Запись: версия — какая была при открытии; изменился на Диске — {конфликт} (страница спросит). */
async function записать(){
  return безВхода(async () => {
    const п = параметры(), путь = путьДиска(п.путь);
    const б = п.байты instanceof Uint8Array ? п.байты : null;
    if(!б) throw new Error('Нечего записывать: нет байтов файла');
    if(б.length > ПРЕДЕЛ_ФАЙЛА) throw new Error('Файл больше 30 МБ — так много за раз не записать');
    const имя = путь.split('/').pop();
    if(п.версия || !п.перезаписать){
      const м = await диск('resources?' + форма({path: путь, fields: 'name,type,size,modified,md5'}), {});
      if(м.ок){
        const есть = версия(м.тело);
        if(!п.перезаписать) return {конфликт: true, есть: true, изменён: (м.тело || {}).modified || ''};
        if(п.версия && есть && !совпадает(есть, п.версия)) return {конфликт: true, изменён: (м.тело || {}).modified || ''};
      } else if(м.код !== 404) throw бедаДиска(м, 'Файл «' + имя + '»');
    }
    const с = await диск('resources/upload?' + форма({path: путь, overwrite: 'true'}), {});
    if(!с.ок || !с.тело || !с.тело.href) throw бедаДиска(с, 'Записать «' + имя + '»');
    const r = await сеть(new URL(с.тело.href).toString(), {метод: String(с.тело.method || 'PUT').toUpperCase(), тело: б, срок: 180000,
      заголовки: {'Content-Type': 'application/octet-stream'}});
    if(!(r.код === 201 || r.код === 202 || r.код === 200)) throw new Error('Файл «' + имя + '» не записан: сервер загрузки ответил ' + r.код);
    /* новая версия — для следующей сверки (Диск досчитывает md5 не сразу: тогда — по дате и размеру) */
    let после = null;
    for(let i = 0; i < 3 && !после; i++){
      const м = await диск('resources?' + форма({path: путь, fields: 'name,path,size,modified,md5'}), {});
      if(м.ок && м.тело && +м.тело.size === б.length) после = м.тело; else await пауза(400);
    }
    return {путь: (после && после.path) || путь, имя, версия: версия(после), изменён: (после && после.modified) || ''};
  });
}
/* версии сравниваются одного вида: md5 с md5, дата с датой */
function совпадает(a, b){
  const ва = String(a).split(':')[0], вб = String(b).split(':')[0];
  if(ва !== вб) return true;                      // разного вида — сверить нечем, не мешаем
  return a === b;
}
async function создатьПапку(){
  return безВхода(async () => {
    const путь = путьДиска(параметры().путь);
    const r = await диск('resources?' + форма({path: путь}), {метод: 'PUT'});
    if(r.код === 201 || r.код === 409) return {путь};
    throw бедаДиска(r, 'Папка «' + путь.split('/').pop() + '»');
  });
}
